from datetime import datetime, timedelta, timezone
from html import escape
import sqlite3
import unittest

from unittest.mock import patch

import test_uniclubs_importer as source_fixtures
import uniclubs_database
import uniclubs_importer


NOW = datetime(2026, 11, 15, 17, 0, tzinfo=timezone.utc)
NEXT = NOW + timedelta(hours=1)
LATER = NOW + timedelta(hours=2)
FETCH_TARGET = 'uniclubs_importer.importers.fetch_uniclubs_sync_documents'

LEGACY_EVENTS_SQL = '''CREATE TABLE events (
    id INTEGER PRIMARY KEY,
    external_id TEXT NOT NULL UNIQUE CHECK (trim(external_id) <> ''),
    club_id INTEGER NOT NULL REFERENCES clubs(id),
    title TEXT NOT NULL CHECK (trim(title) <> ''),
    start_utc TEXT NOT NULL,
    end_utc TEXT,
    location TEXT NOT NULL DEFAULT '',
    event_type TEXT NOT NULL DEFAULT '',
    source_url TEXT NOT NULL CHECK (trim(source_url) <> ''),
    publication_status TEXT NOT NULL DEFAULT 'unknown',
    availability_state TEXT NOT NULL DEFAULT 'unknown',
    requires_membership INTEGER CHECK (requires_membership IN (0, 1)),
    first_seen_utc TEXT NOT NULL,
    last_seen_utc TEXT NOT NULL,
    CHECK (end_utc IS NULL OR end_utc > start_utc),
    CHECK (last_seen_utc >= first_seen_utc)
)'''


def club_record(external_id='club-1', name='Example Club', slug='example-club'):
    """Return the normalized public identity of one fictional club."""
    return {'external_id': external_id, 'name': name,
            'source_url': 'https://uniclubs.ch/hsg/clubs/' + slug}


def event_record(external_id='event-1', **changes):
    """Return one normalized source event with explicit overrides for boundary tests."""
    # Course: L04 – dictionaries keep source identity separate from local database keys.
    record = {
        'external_id': external_id,
        'club_external_id': 'club-1',
        'title': 'Example workshop',
        'start_utc': '2026-11-16T11:00:00Z',
        'end_utc': '2026-11-16T12:00:00Z',
        'location': 'Online',
        'event_type': 'talk',
        'source_url': 'https://uniclubs.ch/hsg/clubs/example-club/events/' + external_id,
        'publication_status': 'published',
        'availability_state': 'open',
        'requires_membership': False,
    }
    record.update(changes)
    return record


def sitemap_page(items, additional_urls=()):
    """Build an XML sitemap for the public URLs of the supplied raw event fixtures."""
    urls = list(additional_urls)
    for item in items:
        urls.append('https://uniclubs.ch/hsg/clubs/' + item['club']['slug'] +
                    '/events/' + item['event']['slug'])
    parts = ['<?xml version="1.0" encoding="UTF-8"?>',
             '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for url in urls:
        parts.append('<url><loc>' + escape(url) + '</loc></url>')
    parts.append('</urlset>')
    return ''.join(parts)


class UniClubsSyncTests(unittest.TestCase):
    """Exercise repeated catalog snapshots without files, real HTTP or legacy databases."""

    def setUp(self):
        """Create an independent catalog connection and its current schema."""
        self.connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_database.init_db(self.connection)

    def sync(self, events=None, clubs=None, now=NOW):
        """Apply a complete normalized fixture snapshot through the real storage function."""
        if events is None:
            events = [event_record()]
        if clubs is None:
            clubs = [club_record()]
        return uniclubs_database.sync_catalog(self.connection, clubs, events, now=now)

    def event(self, external_id='event-1'):
        """Read a stored event by its stable UniClubs identifier."""
        return self.connection.execute('SELECT * FROM events WHERE external_id=?',
                                       (external_id,)).fetchone()

    def snapshot(self):
        """Capture all catalog tables to detect partial writes and unintended commits."""
        clubs = self.connection.execute('SELECT * FROM clubs ORDER BY id').fetchall()
        events = self.connection.execute('SELECT * FROM events ORDER BY id').fetchall()
        logs = self.connection.execute('SELECT * FROM import_log ORDER BY id').fetchall()
        return ([tuple(row) for row in clubs], [tuple(row) for row in events],
                [tuple(row) for row in logs])

    def test_repeated_snapshot_preserves_identity_and_reports_unchanged(self):
        """Advancing observation time must not create another event or count an edit."""
        first = self.sync()
        original = self.event()
        second = self.sync(now=NEXT)
        current = self.event()
        self.assertEqual(first['events_added'], 1)
        self.assertEqual(second['events_added'], 0)
        self.assertEqual(second['events_updated'], 0)
        self.assertEqual(second['events_unchanged'], 1)
        self.assertEqual(current['id'], original['id'])
        self.assertEqual(current['first_seen_utc'], original['first_seen_utc'])
        self.assertEqual(current['last_seen_utc'], '2026-11-15T18:00:00.000000Z')
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 1)
        self.assertEqual(len(uniclubs_database.get_import_log(self.connection)), 2)

    def test_new_source_id_is_added_even_when_title_is_identical(self):
        """Repeated titles do not merge distinct UniClubs events or duplicate old ones."""
        self.sync()
        result = self.sync([event_record(), event_record('event-2')], now=NEXT)
        self.assertEqual(result['events_added'], 1)
        self.assertEqual(result['events_unchanged'], 1)
        self.assertNotEqual(self.event()['id'], self.event('event-2')['id'])
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 2)

    def test_title_place_and_time_changes_update_the_same_local_event(self):
        """A rescheduled event retains its identity and original first observation."""
        self.sync()
        original = self.event()
        changed = event_record(title="Club's revised workshop", location='Room 01-106',
                               start_utc='2026-11-17T13:00:00Z',
                               end_utc='2026-11-17T15:30:00Z')
        result = self.sync([changed], now=NEXT)
        current = self.event()
        self.assertEqual(result['events_updated'], 1)
        self.assertEqual(result['events_added'], 0)
        self.assertEqual(current['id'], original['id'])
        self.assertEqual(current['first_seen_utc'], original['first_seen_utc'])
        self.assertEqual(current['title'], changed['title'])
        self.assertEqual(current['location'], changed['location'])
        self.assertEqual(current['start_utc'], '2026-11-17T13:00:00.000000Z')

    def test_known_past_event_is_updated_but_new_historical_event_is_not_added(self):
        """A moved start in the past must still update a previously imported identifier."""
        self.sync()
        original_id = self.event()['id']
        known = event_record(start_utc='2026-11-14T11:00:00Z',
                             end_utc='2026-11-14T12:00:00Z', title='Corrected past date')
        historical = event_record('historical', start_utc='2026-11-13T11:00:00Z',
                                  end_utc='2026-11-13T12:00:00Z')
        result = self.sync([known, historical], now=NEXT)
        self.assertEqual(result['events_updated'], 1)
        self.assertEqual(result['events_added'], 0)
        self.assertEqual(result['events_missing'], 0)
        self.assertEqual(self.event()['id'], original_id)
        self.assertEqual(self.event()['title'], 'Corrected past date')
        self.assertEqual(self.event()['source_missing'], 0)
        self.assertIsNone(self.event('historical'))

    def test_known_ongoing_event_is_not_mistaken_for_a_missing_source(self):
        """The full source retains known offers after their start has passed."""
        self.sync()
        ongoing = event_record(start_utc='2026-11-15T16:00:00Z',
                               end_utc='2026-11-15T20:00:00Z')
        result = self.sync([ongoing], now=NEXT)
        self.assertEqual(result['events_updated'], 1)
        self.assertEqual(result['events_missing'], 0)
        self.assertEqual(self.event()['source_missing'], 0)
        self.assertEqual(self.event()['start_utc'], '2026-11-15T16:00:00.000000Z')

    def test_explicit_cancellation_and_closed_registration_remain_distinct(self):
        """Only a published source cancellation may replace the publication status."""
        self.sync([event_record(), event_record('event-2')])
        cancelled = event_record(publication_status='cancelled')
        closed = event_record('event-2', availability_state='sales_closed',
                              requires_membership=True)
        result = self.sync([cancelled, closed], now=NEXT)
        self.assertEqual(result['events_updated'], 2)
        self.assertEqual(self.event()['publication_status'], 'cancelled')
        self.assertEqual(self.event('event-2')['publication_status'], 'published')
        self.assertEqual(self.event('event-2')['availability_state'], 'sales_closed')
        self.assertEqual(self.event('event-2')['requires_membership'], 1)

    def test_missing_and_returning_event_preserves_metadata_and_original_identity(self):
        """Absence marks uncertainty while reappearance restores the same event row."""
        self.sync([event_record(), event_record('event-2')])
        original = self.event()
        missing = self.sync([event_record('event-2')], now=NEXT)
        absent = self.event()
        self.assertEqual(missing['events_missing'], 1)
        self.assertEqual(missing['events_marked_missing'], 1)
        self.assertEqual(absent['source_missing'], 1)
        for field in ('id', 'title', 'publication_status', 'last_seen_utc', 'first_seen_utc'):
            self.assertEqual(absent[field], original[field])
        restored = self.sync([event_record(), event_record('event-2')], now=LATER)
        self.assertEqual(restored['events_restored'], 1)
        self.assertEqual(restored['events_updated'], 1)
        self.assertEqual(self.event()['source_missing'], 0)
        self.assertEqual(self.event()['id'], original['id'])
        self.assertEqual(self.event()['first_seen_utc'], original['first_seen_utc'])

    def test_club_rename_and_event_club_change_preserve_event_identity(self):
        """Changing a club's metadata or assignment must not replace the event row."""
        self.sync()
        original = self.event()
        rename = self.sync(clubs=[club_record(name='Renamed Club')], now=NEXT)
        self.assertEqual(rename['clubs_updated'], 1)
        joined = uniclubs_database.get_events(self.connection)[0]
        self.assertEqual(joined['club_name'], 'Renamed Club')
        self.assertEqual(joined['club_id'], original['club_id'])
        second = club_record('club-2', 'Second Club', 'second-club')
        moved = event_record(club_external_id='club-2')
        changed = self.sync([moved], clubs=[second], now=LATER)
        self.assertEqual(changed['clubs_added'], 1)
        self.assertEqual(changed['events_updated'], 1)
        self.assertEqual(self.event()['id'], original['id'])
        self.assertNotEqual(self.event()['club_id'], original['club_id'])
        self.assertEqual(uniclubs_database.get_events(self.connection)[0]['club_name'],
                         'Second Club')

    def test_late_invalid_record_rolls_back_clubs_events_flags_and_success_log(self):
        """A failing later update must undo every change in its synchronization attempt."""
        self.sync([event_record(), event_record('event-2')])
        before = self.snapshot()
        changed = event_record(title='Must not be committed')
        invalid = event_record('event-3', title='')
        with self.assertRaises(ValueError):
            self.sync([changed, invalid], clubs=[club_record(name='Must not be committed')],
                      now=NEXT)
        self.assertEqual(self.snapshot(), before)

    def test_empty_duplicate_and_orphan_source_records_do_not_mutate_catalog(self):
        """Reject ambiguous or invalid snapshots before retaining any partial changes."""
        self.sync()
        before = self.snapshot()
        cases = [([], [club_record()]),
                 ([event_record(), event_record()], [club_record()]),
                 ([event_record(club_external_id='missing')], [club_record()])]
        for events, clubs in cases:
            with self.subTest(events=events):
                with self.assertRaises(ValueError):
                    self.sync(events, clubs=clubs, now=NEXT)
                self.assertEqual(self.snapshot(), before)

    def test_success_log_write_failure_rolls_back_all_prior_snapshot_changes(self):
        """A database error after writes must undo edits, new rows and missing markers."""
        self.sync([event_record(), event_record('event-2')])
        before = self.snapshot()
        with self.connection:
            self.connection.execute('''CREATE TRIGGER reject_success_log
                BEFORE INSERT ON import_log WHEN NEW.status = 'success'
                BEGIN SELECT RAISE(ABORT, 'injected final write failure'); END''')
        changed = event_record(title='Must roll back')
        added = event_record('later')
        with self.assertRaises(sqlite3.IntegrityError):
            self.sync([changed, added], clubs=[club_record(name='Must roll back')], now=NEXT)
        self.assertEqual(self.snapshot(), before)
        self.assertIsNone(self.event('later'))
        self.assertEqual(self.event('event-2')['source_missing'], 0)

    def test_older_snapshot_clock_cannot_overwrite_newer_observations(self):
        """Reject an older injected clock without rewriting data or its successful log."""
        self.sync()
        self.sync([event_record(title='Latest known title')], now=NEXT)
        before = self.snapshot()
        with self.assertRaises(ValueError):
            self.sync([event_record(title='Stale title')], now=NOW)
        self.assertEqual(self.snapshot(), before)

    def test_open_caller_transaction_is_refused_without_losing_pending_data(self):
        """Synchronization must not commit or roll back work owned by its caller."""
        self.connection.execute('''INSERT INTO clubs (external_id, name, source_url)
            VALUES (?, ?, ?)''', ('pending', 'Pending club', club_record()['source_url']))
        with self.assertRaises(ValueError):
            self.sync()
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)
        self.assertEqual(uniclubs_database.get_import_log(self.connection), [])
        self.connection.rollback()

    def test_schema_migration_keeps_legacy_event_ids_times_and_foreign_keys(self):
        """Add the missing-source marker to a Task 3 schema without replacing its rows."""
        legacy = uniclubs_database.get_connection(':memory:')
        self.addCleanup(legacy.close)
        with legacy:
            for statement in uniclubs_database.SCHEMA:
                if statement.lstrip().startswith('CREATE TABLE IF NOT EXISTS events'):
                    legacy.execute(LEGACY_EVENTS_SQL)
                else:
                    legacy.execute(statement)
        club_id = uniclubs_database.add_club(legacy, 'old-club', 'Old Club',
                                            club_record()['source_url'])
        record = event_record()
        record['club_id'] = club_id
        event_id = uniclubs_database.add_event(legacy, record, now=NOW)
        before = legacy.execute('SELECT * FROM events').fetchone()
        self.assertNotIn('source_missing', before.keys())
        uniclubs_database.init_db(legacy)
        uniclubs_database.init_db(legacy)
        after = legacy.execute('SELECT * FROM events').fetchone()
        self.assertEqual(after['id'], event_id)
        self.assertEqual(after['source_missing'], 0)
        for field in before.keys():
            self.assertEqual(after[field], before[field])
        self.assertEqual(legacy.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_parser_retains_the_full_source_for_known_historical_updates(self):
        """Full source output must retain past events in addition to the future selection."""
        raw = [source_fixtures.source_event(),
               source_fixtures.source_event('past', 'past',
                                            startDate='$D2026-11-14T11:00:00Z',
                                            endDate='$D2026-11-14T12:00:00Z')]
        result = uniclubs_importer.parse_events_page(source_fixtures.source_page(raw), now=NOW)
        self.assertEqual(len(result['events']), 1)
        self.assertEqual(len(result['source_events']), 2)
        self.assertEqual(len(result['source_clubs']), 1)
        self.assertEqual({event['external_id'] for event in result['source_events']},
                         {'event-1', 'past'})

    def test_sitemap_verification_accepts_complete_scope_and_rejects_bad_documents(self):
        """Only a valid sitemap with all source event URLs can verify the snapshot."""
        raw = [source_fixtures.source_event()]
        result = uniclubs_importer.parse_events_page(source_fixtures.source_page(raw), now=NOW)
        extra = ('https://uniclubs.ch/hsg/clubs/example-club',
                 'https://uniclubs.ch/eth/clubs/another-club/events/another-event')
        uniclubs_importer.verify_sitemap(result, sitemap_page(raw, additional_urls=extra))
        for xml in ('<broken', sitemap_page([]),
                    sitemap_page([], additional_urls=('https://example.org/elsewhere',))):
            with self.subTest(xml=xml):
                with self.assertRaises(ValueError):
                    uniclubs_importer.verify_sitemap(result, xml)

    def test_sitemap_detects_jointly_shortened_data_and_visible_event_links(self):
        """A self-consistent shortened HTML page must still fail the independent URL check."""
        first = source_fixtures.source_event()
        second = source_fixtures.source_event('event-2', 'second')
        short = uniclubs_importer.parse_events_page(
            source_fixtures.source_page([first]), now=NOW)
        with self.assertRaises(ValueError):
            uniclubs_importer.verify_sitemap(short, sitemap_page([first, second]))

    def test_run_sync_repeatedly_updates_observations_without_duplicates(self):
        """The complete mocked download-to-storage workflow must support a populated catalog."""
        raw = [source_fixtures.source_event()]
        documents = (source_fixtures.source_page(raw), sitemap_page(raw))
        with patch(FETCH_TARGET, return_value=documents) as fetch:
            first = uniclubs_importer.run_sync(self.connection, now=NOW)
            second = uniclubs_importer.run_sync(self.connection, now=NEXT)
        self.assertEqual(fetch.call_count, 2)
        self.assertEqual(first['events_added'], 1)
        self.assertEqual(second['events_unchanged'], 1)
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 1)

    def test_failed_sync_preserves_data_and_logs_only_sanitized_errors(self):
        """HTTP, parser and sitemap failures leave catalog rows and observations untouched."""
        self.sync()
        before = self.snapshot()[:2]
        raw = [source_fixtures.source_event()]
        malformed = ('<html>Service unavailable</html>', sitemap_page(raw))
        mismatch = (source_fixtures.source_page(raw), sitemap_page([]))
        for documents in (malformed, mismatch):
            with self.subTest(documents=documents):
                with patch(FETCH_TARGET, return_value=documents):
                    with self.assertRaises(ValueError):
                        uniclubs_importer.run_sync(self.connection, now=NEXT)
                self.assertEqual(self.snapshot()[:2], before)
                self.assertEqual(uniclubs_database.get_import_log(self.connection)[0]['status'],
                                 'error')
        with patch(FETCH_TARGET, side_effect=ValueError('private-source-marker')):
            with self.assertRaises(ValueError):
                uniclubs_importer.run_sync(self.connection, now=NEXT)
        self.assertEqual(self.snapshot()[:2], before)
        self.assertNotIn('private-source-marker',
                         uniclubs_database.get_import_log(self.connection)[0]['message'])

    def test_run_sync_can_update_a_known_event_without_any_future_starts(self):
        """A valid all-past source must still update known identifiers instead of failing empty."""
        self.sync()
        past = source_fixtures.source_event(startDate='$D2026-11-14T11:00:00Z',
                                            endDate='$D2026-11-14T12:00:00Z',
                                            title='Corrected past source')
        documents = (source_fixtures.source_page([past]), sitemap_page([past]))
        with patch(FETCH_TARGET, return_value=documents):
            result = uniclubs_importer.run_sync(self.connection, now=NEXT)
        self.assertEqual(result['future_event_count'], 0)
        self.assertEqual(result['events_updated'], 1)
        self.assertEqual(self.event()['title'], 'Corrected past source')
        self.assertEqual(self.event()['source_missing'], 0)

    def test_source_missing_marker_rejects_values_other_than_zero_or_one(self):
        """The database itself must enforce the separate missing-source boolean."""
        self.sync()
        original = tuple(self.event())
        with self.assertRaises(sqlite3.IntegrityError):
            with self.connection:
                self.connection.execute('UPDATE events SET source_missing=? WHERE external_id=?',
                                        (2, 'event-1'))
        self.assertEqual(tuple(self.event()), original)


